var _default = uiLogic.default;
const webhookurl=_default.webhookurl;
const webhookdebugparams=_default.webhookdebugparams  || {} ;
const url = new URL(webhookurl);
const headers = {
    "Content-Type": "application/json"
};

fetch(url, {
    method: 'POST',
    headers: headers,
    body: webhookdebugparams
});

ibiz.message.success('执行指令已发出...');

var model_data = uiLogic.default.model_data;
if (model_data) {
    try {
        var dataObj = JSON.parse(model_data);
        dataObj.updatedate = null;
        dataObj.updateman = null;
        uiLogic.default = dataObj;
        console.log("------更新后的model数据-----", uiLogic.default);
    } catch (e) {
        console.error("JSON 解析失败，请检查数据格式", e);
    }
} else {
    console.warn("model_data 为空，不进行模型更新");
}
